Definition fflag (L : alayout) (c F : Z) : Z := fk_flags L c + (F - fk_frames L c) / fk_fsize c.
(* [comment removed for export] *)
Definition fk_hint (L : alayout) (c : Z) : Z := al_fake L + 8 * c.

